"""Pinned BWAPI Medic and organic flags; OpenBW healing fixed-point facts."""
import hashlib,json,re,sys
from pathlib import Path
root=Path(sys.argv[1] if len(sys.argv)>1 else 'work/sources');u=(root/'unit.cpp').read_text();t=(root/'tech.cpp').read_text();up=(root/'upgrade.cpp').read_text();engine=(root/'bwgame.h').read_text()
def body(s,n):
 s=re.sub(r'//[^\n]*','',s);m=re.search(re.escape(n)+r'\[[^\]]+\]\s*=\s*\{(.*?)\};',s,re.S);assert m,n;return m[1]
def nums(s,n):return [float(x) for x in re.findall(r'-?\d+(?:\.\d+)?',body(s,n))]
def words(s,n):return re.findall(r'\b[A-Za-z_][A-Za-z_0-9]*\b',body(s,n))
def names(s):return re.findall(r'"([^"]*)"',body(s,'typeNames'))
un=names(u);tn=names(t);upn=names(up);i=un.index('Terran_Medic');dims=[[int(x)for x in re.findall(r'\d+',v)]for v in re.findall(r'\{([^{}]+)\}',body(u,'unitDimensions'))];flags=body(u,'unitFlags').split(',');columns=['defaultOreCost','defaultGasCost','defaultTimeCost','defaultMaxHP','defaultMaxSP','defaultArmorAmount','unitSupplyProvided','unitSupplyRequired','unitTopSpeeds','sightRangeTiles'];unit={'name':'Terran_Medic','bwapiId':i,**{k:nums(u,k)[i] for k in columns},'dimensions':dims[i]};unit={k:int(v)if isinstance(v,float)and v.is_integer()else v for k,v in unit.items()}
profile={'name':'Terran_Medic','size':words(u,'unitSize')[i].lower(),'bounds':dims[i][2:],'groundWeapon':words(u,'groundWeapon')[i],'airWeapon':words(u,'airWeapon')[i],'hits':int(nums(u,'groundWeaponHits')[i])};trait={'name':'Terran_Medic','spaceRequired':int(nums(u,'unitSpaceRequired')[i]),'spaceProvided':int(nums(u,'unitSpaceProvided')[i]),'flyer':False,'detector':False,'permanentCloak':False}
assert 'Gas price is exactly the same as mineral price' in up
assert 'square_at(u->sprite->position, 160)' in engine[engine.index('unit_t* find_medic_target'):engine.index('int medic_try_heal')]
j=upn.index('Caduceus_Reactor');upgrade={'name':'Caduceus_Reactor','unitId':'terran-medic','title':'카두세우스 반응로','producer':words(up,'whatUpgrades')[j].lower().replace('_','-'),'minerals':int(nums(up,'defaultOreCostBase')[j]),'gas':int(nums(up,'defaultOreCostBase')[j]),'frames':int(nums(up,'defaultTimeCostBase')[j]),'maxLevel':int(nums(up,'defaultMaxRepeats')[j])}
heal=engine[engine.index('int medic_try_heal'):engine.index('bool tile_has_creep')];amount=int(re.search(r'heal_amount > (\d+)_fp8',heal)[1]);divisor=int(re.search(r'energy_required = heal_amount / (\d+)',heal)[1]);range_pixels=int(re.search(r'unit_target_in_range\(u, target, (\d+)\)',heal)[1]);tech=tn.index('Healing');minimum=int(nums(t,'defaultEnergyCost')[tech]);assert (amount,divisor,range_pixels,minimum)==(200,2,30,1)
commit=json.loads((root/'openbw-commit.json').read_text())['sha'];out={'source':{'reference':'BWAPI v4.4.0 / Brood War1.16.1; pinned OpenBW Medic healing','bwapiUrl':'https://github.com/bwapi/bwapi/tree/v4.4.0/bwapi/BWAPILIB/Source','openbwUrl':f'https://github.com/OpenBW/openbw/blob/{commit}/bwgame.h','sha256':{n:hashlib.sha256(v.encode()).hexdigest()for n,v in [('UnitType.cpp',u),('TechType.cpp',t),('UpgradeType.cpp',up),('bwgame.h',engine)]}},'units':[unit],'profiles':[profile],'traits':[trait],'weapons':[],'upgrade':upgrade,'organicUnits':[n.lower().replace('_','-') for n,f in zip(un,flags)if 'Organic' in f],'healing':{'amountPerFrame':amount,'energyDivisor':divisor,'minimumEnergy':minimum,'rangePixels':range_pixels,'acquirePixels':160,'framesPerSecond':24,'scale':256}}
Path('app/stark-rift/data/medic-original.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'unit':unit,'upgrade':upgrade,'healing':out['healing'],'scvOrganic':'terran-scv'in out['organicUnits']},ensure_ascii=False))
